#include "menu/localization/LanguagePack.h"
#include <iostream>
using namespace Neurotic::Localization;
int main(){
 int failed=0;auto check=[&](bool ok,const char* message){std::cout<<(ok?"PASS ":"FAIL ")<<message<<'\n';failed+=!ok;};
 EnglishCatalog english;english.emplace("desktop.install.conflict",EnglishEntry{"desktop.install.conflict","desktop","installation","warning","{filename} appears to not have come from NeuRotic. How should we proceed?","Foreign file decision",{{"filename","text"}},{"NeuRotic"},false,2});english.emplace("ingame.nr.waiting",EnglishEntry{"ingame.nr.waiting","in_game","nr","status","Waiting for guides.","Guide intake status",{}, {},false,1});
 auto pack=[](){return Json{{"formatVersion",1},{"packId","fixture-v1"},{"locale","de"},{"language","Deutsch"},{"name","Fixture"},{"author","Test"},{"version","1"},{"desktop",Json::array()},{"in_game",Json::array()}};};
 auto entry=[](const char* id,const char* text,int revision=1){return Json{{"id",id},{"translation",text},{"revision",revision}};};
 auto data=pack();data["desktop"].push_back(entry("desktop.install.conflict","{filename} stammt anscheinend nicht von NeuRotic. Wie sollen wir fortfahren?",1));data["in_game"].push_back(entry("ingame.nr.waiting","Warten auf Guides."));
 auto valid=ValidatePack(data.dump(),english);check(valid.accepted&&valid.pack.entries.size()==2,"partial pack accepted across both surfaces");
 CatalogLayers layers{&english,nullptr,&valid.pack,nullptr};auto resolved=Resolve(layers,"desktop.install.conflict");check(resolved.layer==Layer::Community&&resolved.needsReview,"usable stale translation precedes English");check(Format(resolved,{{"filename",std::string("dxgi.dll")}}).starts_with("dxgi.dll stammt"),"named format substitutes data safely");
 auto localData=pack();localData["desktop"].push_back(entry("desktop.install.conflict","NeuRotic: {filename} ist fremd.",2));auto local=ValidatePack(localData.dump(),english);layers.local=&local.pack;check(Resolve(layers,"desktop.install.conflict").layer==Layer::Local,"local edit wins");
 auto blank=data;blank["desktop"][0]["translation"]="";auto blankPack=ValidatePack(blank.dump(),english);layers.local=&blankPack.pack;check(Resolve(layers,"desktop.install.conflict").layer==Layer::Community,"blank local falls through per entry");
 auto bad=data;bad["desktop"][0]["translation"]="NeuRotic ohne Dateiname";auto partial=ValidatePack(bad.dump(),english);check(partial.accepted&&partial.errors.size()==1&&partial.pack.entries.size()==1,"invalid placeholder rejects only affected entry");layers.local=&partial.pack;check(Resolve(layers,"desktop.install.conflict").layer==Layer::Community,"invalid local retains community fallback");
 layers.local=nullptr;layers.community=nullptr;layers.bundled=&valid.pack;check(Resolve(layers,"desktop.install.conflict").layer==Layer::Bundled,"bundled before English");layers.bundled=nullptr;check(Resolve(layers,"desktop.install.conflict").text==english.at("desktop.install.conflict").english,"canonical final fallback");
 auto unknown=data;unknown["desktop"].push_back(entry("desktop.old.removed","Obsolete"));auto old=ValidatePack(unknown.dump(),english);check(old.accepted&&old.pack.obsolete.size()==1&&!old.pack.entries.contains("desktop.old.removed"),"unknown IDs round trip without activation");
 auto dup=data;dup["desktop"].push_back(dup["desktop"][0]);check(!ValidatePack(dup.dump(),english).accepted,"duplicate IDs rejected");
 check(!ValidatePack("{\"formatVersion\":1,\"formatVersion\":1}",english).accepted,"duplicate JSON keys rejected");
 for(auto field:{"command","font","path","script","images"}){auto unsafe=data;unsafe[field]="untrusted";check(!ValidatePack(unsafe.dump(),english).accepted,"executable and asset fields rejected");}
 auto version=data;version["formatVersion"]=9;check(!ValidatePack(version.dump(),english).accepted,"unsupported format rejected");auto locale=data;locale["locale"]="../../escape";check(!ValidatePack(locale.dump(),english).accepted,"invalid locale rejected");
 check(!ValidatePack("[invalid",english).accepted,"malformed JSON rejected");check(!ValidatePack(std::string(16777217,'x'),english).accepted,"file size bound before parse");
 auto nul=data;nul["desktop"][0]["translation"]=std::string("NeuRotic {filename}\0bad",22);check(ValidatePack(nul.dump(),english).pack.entries.size()==1,"NUL entry unusable");auto preserved=data;preserved["desktop"][0]["translation"]="Andere {filename}";check(ValidatePack(preserved.dump(),english).errors.size()==1,"required product term preserved");
 bool mismatch=false;try{Format(resolved,{{"other",std::string("file")}});}catch(...){mismatch=true;}check(mismatch,"format refuses missing or extra arguments");
 auto utf=data.dump();utf.insert(utf.find("Warten"),1,char(0xff));check(!ValidatePack(utf,english).accepted,"invalid UTF-8 rejected");
 check(ValidLocale("zh-Hans-CN")&&ValidLocale("pt-BR")&&ValidLocale("x-my-language")&&!ValidLocale("en-invalidsubtag")&&!ValidLocale("en--US"),"BCP 47 script, region and private-use boundaries");
 auto oversized=data;oversized["in_game"][0]["translation"]=std::string(32769,'a');auto large=ValidatePack(oversized.dump(),english);check(large.accepted&&large.errors.size()==1&&large.pack.entries.size()==1,"individual string bound preserves other entries");
 auto wrong=data;wrong["desktop"].push_back(entry("ingame.nr.waiting","Warten"));wrong["in_game"]=Json::array();auto wrongSurface=ValidatePack(wrong.dump(),english);check(wrongSurface.accepted&&wrongSurface.errors.size()==1,"wrong surface rejected per entry");
 auto deep=data;Json nested=Json::array();for(int i=0;i<20;++i)nested=Json::array({nested});deep["desktop"][0]["context"]=nested;check(!ValidatePack(deep.dump(),english).accepted,"nesting bound prevents deeply nested untrusted data");
 bool wrongType=false;try{Format(resolved,{{"filename",int64_t(42)}});}catch(...){wrongType=true;}check(wrongType,"format enforces argument types");
 auto hostile=data;hostile["in_game"][0]["translation"]="%"+std::string(31000,'9')+"f";auto hostileResult=ValidatePack(hostile.dump(),english);check(hostileResult.accepted&&hostileResult.errors.size()==1&&hostileResult.pack.entries.size()==1,"long untrusted format token cannot exhaust the parser");
 EnglishEntry timing{"ingame.frame.timing","in_game","diagnostics","status","Frame time: %7.2f ms / %6.1f FPS","Observed frame timing",{{"arg1","number"},{"arg2","number"}}, {},false,1};english.emplace(timing.id,timing);
 auto timingText=Resolve({&english},timing.id);check(Format(timingText,{{"arg1",16.6667},{"arg2",60.0}})=="Frame time:   16.67 ms /   60.0 FPS","complete typed printf template retains numeric precision and widths");
 auto metadata=data;metadata["name"]=std::string(256,'a');check(!ValidatePack(metadata.dump(),english).accepted,"single-line metadata fits editor fields without truncation");metadata=data;metadata["author"]="A\nB";check(!ValidatePack(metadata.dump(),english).accepted,"metadata cannot inject additional interface rows");
 check(!locale.is_null()&&!ValidatePack(locale.dump(),english).errorCode.empty(),"structural errors carry a stable presentation code");check(!partial.errors.front().reasonCode.empty(),"individual invalid entries retain their presentation code");
 EnglishEntry bounded{"ingame.format.bounded","in_game","nr","status","Guide: %.*s","Bounded detail",{{"arg1","integer"},{"arg2","text"}}, {},false,1};english.emplace(bounded.id,bounded);auto boundedData=pack();boundedData["in_game"].push_back(entry(bounded.id.c_str(),"Guide: %.*n"));check(ValidatePack(boundedData.dump(),english).errors.size()==1,"dynamic precision cannot be changed into an authored printf write directive");
 check(Format(Resolve({&english},bounded.id),{{"arg1",int64_t(4)},{"arg2",std::string("Depth input")}})=="Guide: Dept","typed dynamic precision renders a bounded inserted value");
 return failed?1:0;
}
